1	import * as THREE from 'three';
2	import { CONFIG } from '../../config';
3	import { shared } from '../../core/shared';
4	
5	/* =====================================================================
6	   VẬT LIỆU NGƯỜI ĐI BỘ — một vật liệu dùng chung cho mọi hệ người (spec G5–G8, §5), theo patchPerson của bản dựng thử.
7	   Tay chân vung trong vertex shader theo shared.uTime, không cập nhật đỉnh trên CPU. Công thức góc khớp giống hệt gait.ts (ppAngles).
8	   Thuộc tính instance (bên dựng gắn vào hình học của từng InstancedMesh):
9	   - aVar (vec4): x pha φ0 (rad), y biên độ hông A (0 đứng, walk.amp, run.amp), z cờ (1 nón lá, 2 ba lô, 4 chụp ảnh), w nhịp (rad/s, ppCadence)
10	   - aPants (vec3): màu quần tuyến tính; màu áo qua instanceColor (setColorAt — bắt buộc gọi để có USE_INSTANCING_COLOR)
11	   Người không đổ bóng, không vào phản chiếu (spec §6) nên không có vật liệu bóng riêng. Không emissive, không texture.
12	   Không thêm vào tập bóc mặt cắt hầm (cutaway.ts): người không đứng trong vùng bóc, vật liệu người cũ cũng không có trong tập đó.
13	   ===================================================================== */
14	const P = CONFIG.people;
15	const f = (x: number) => x.toFixed(4);   // số → hằng GLSL
16	
17	/* pAngles: x góc khớp gốc (hông / vai), y góc khớp giữa (gối / khuỷu); dương = đưa về phía trước. Bản CPU: gait.ts ppAngles */
18	const VS_HEAD = /* glsl */`
19	attribute float aPart;
20	attribute float aSeg;
21	attribute float aPivot;
22	attribute float aPivot2;
23	attribute float aMask;
24	attribute vec3 aFix;
25	attribute vec4 aVar;
26	attribute vec3 aPants;
27	uniform float uTime;
28	float pFlag( float b ) { return mod( floor( aVar.z / b ), 2.0 ); }
29	float pRunMix() { return smoothstep( 0.42, 0.6, aVar.y ); }
30	float pPhase() { return uTime * aVar.w + aVar.x; }
31	vec2 pAngles() {
32	  float A = aVar.y, ph = pPhase(), run = pRunMix();
33	  if ( aPart > 0.5 && aPart < 2.5 ) {
34	    float fl = aPart < 1.5 ? ph : ph + 3.14159265;
35	    float sw = max( 0.0, cos( fl - 0.35 ) ), sr = max( 0.0, cos( fl + 0.45 ) );   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
36	    return vec2( A * sin( fl ) + mix( 0.12 * A, 0.22, run ), -mix( A * 2.0 * sw * sw + 0.06 * step( 0.01, A ), 0.38 + 1.5 * sr * sr, run ) );
37	  }
38	  if ( aPart > 2.5 && aPart < 4.5 ) {
39	    float fa = aPart < 3.5 ? ph + 3.14159265 : ph;
40	    if ( aPart > 3.5 && pFlag( 4.0 ) > 0.5 ) return vec2( ${f(P.photo.shoulder)}, ${f(P.photo.elbow)} );   // giơ tay phải chụp ảnh
41	    return vec2( A * ( 0.65 + run * 0.5 ) * sin( fa ) - 0.05, 0.16 + run * 1.25 + A * 0.35 * max( 0.0, sin( fa ) ) );
42	  }
43	  return vec2( 0.0 );
44	}
45	vec2 pRot( vec2 p, float a ) { float c = cos( a ), s = sin( a ); return vec2( p.x * c - p.y * s, p.x * s + p.y * c ); }
46	`;
47	// pháp tuyến quay cùng khớp (beginnormal_vertex chạy trước begin_vertex nên ppA dùng lại được)
48	const VS_NORMAL = /* glsl */`#include <beginnormal_vertex>
49	vec2 ppA = pAngles();
50	float ppLean = ( aPart < 0.5 || aPart > 2.5 ) ? -${f(P.run.lean)} * pRunMix() : 0.0;
51	objectNormal.xy = pRot( objectNormal.xy, ppA.x + ( aSeg > 0.5 ? ppA.y : 0.0 ) + ppLean );`;
52	const VS_POS = /* glsl */`#include <begin_vertex>
53	if ( aSeg > 0.5 ) transformed.xy = pRot( transformed.xy - vec2( 0.0, aPivot2 ), ppA.y ) + vec2( 0.0, aPivot2 );
54	transformed.xy = pRot( transformed.xy - vec2( 0.0, aPivot ), ppA.x ) + vec2( 0.0, aPivot );
55	transformed.xy = pRot( transformed.xy - vec2( 0.0, ${f(P.legLength)} ), ppLean ) + vec2( 0.0, ${f(P.legLength)} );   // chạy: thân, đầu, tay đổ về trước quanh hông
56	if ( aPart > 4.5 && aPart < 5.5 && pFlag( 1.0 ) < 0.5 ) transformed = vec3( 0.0 );   // không đội nón: thu về gốc (tam giác suy biến)
57	if ( aPart > 5.5 && pFlag( 2.0 ) < 0.5 ) transformed = vec3( 0.0 );                  // không đeo ba lô
58	float ppPh = pPhase(), ppMove = step( 0.01, aVar.y );
59	transformed.y += mix( ${f(P.bob.walk)} * cos( 2.0 * ppPh ) - ${f(P.bob.walk)}, ${f(P.bob.run)} * ( 0.5 - 0.5 * cos( 2.0 * ppPh ) ), pRunMix() ) * ppMove;   // đi: thấp nhất khi hai chân dang rộng; chạy: bật lên giữa hai bước
60	transformed.z += ${f(P.sway)} * sin( ppPh ) * ppMove * smoothstep( 0.3, 1.6, transformed.y );   // lắc vai nhẹ sang hai bên`;
61	const VS_COLOR = /* glsl */`#include <color_vertex>
62	#ifdef USE_INSTANCING_COLOR
63	vColor.rgb = aMask < 0.5 ? aFix : ( aMask < 1.5 ? instanceColor.rgb : aPants );   // cố định / áo / quần
64	#endif`;
65	
66	let mat: THREE.MeshStandardMaterial | null = null;
67	/* Một vật liệu cho mọi hệ người (tạo lần đầu gọi) */
68	export function ppMaterial(): THREE.MeshStandardMaterial {
69	  if (mat) return mat;
70	  const m = new THREE.MeshStandardMaterial({ roughness: P.roughness });
71	  m.name = 'peopleWalk';
72	  m.onBeforeCompile = (s) => {
73	    s.uniforms.uTime = shared.uTime;
74	    s.vertexShader = VS_HEAD + s.vertexShader.replace('#include <beginnormal_vertex>', VS_NORMAL).replace('#include <begin_vertex>', VS_POS).replace('#include <color_vertex>', VS_COLOR);
75	    m.userData.vs = s.vertexShader;
76	  };
77	  m.customProgramCacheKey = () => 'peopleWalk';
78	  return (mat = m);
79	}
80

