1	import { CONFIG } from '../../config';
2	import { rng } from '../math';
3	import type { PersonKind } from './gait';
4	
5	/* =====================================================================
6	   CHIA KIỂU NGƯỜI (spec G8, §7) — chọn theo chỉ số trên danh sách người đang có, tổng số không đổi.
7	   Dùng rng(seed) riêng (không gọi rand(), không đụng rnd của cầu). Số người mỗi kiểu = làm tròn n × CONFIG.people.mix.
8	   - Người đi cùng (đi đôi hoặc trẻ em) i luôn theo người i − 1; người i − 1 đi bộ một mình (không chạy, không đứng, không đi cùng ai).
9	   - Trẻ em: tỉ lệ childScale, luôn là người đi cùng. Người chụp ảnh: chỉ trong số người đứng.
10	   - flags = tổng cờ PP_FLAG (khớp aVar.z trong material.ts).
11	   ===================================================================== */
12	export const PP_FLAG = { hat: 1, pack: 2, photo: 4 } as const;
13	export interface PersonInfo { kind: PersonKind; scale: number; flags: number; phase: number; follow: number /* chỉ số người mình đi cùng, −1 nếu không */ }
14	
15	/* Xáo trộn Fisher–Yates bằng bộ sinh r */
16	function ppShuffle<T>(a: T[], r: () => number): T[] {
17	  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
18	  return a;
19	}
20	
