1	/* ===== Dù lượn nhiều người: dù của người bay cùng =====
2	   Mỗi slot một dù màu riêng (multiParams.colors[slot]), dựng lần đầu slot có người (sync) rồi tái dùng; hình học dùng chung, vật liệu riêng.
3	   Vị trí nhận 5 lần/s được nội suy theo giờ gửi của từng người (ExTrack.feed), lấy mẫu chậm interpSends chu kỳ để luôn có hai mẫu kẹp. Slot đổi chủ (đổi tên, hoặc từ trống sang có người)
4	   thì xóa mẫu cũ và ẩn dù tới khi có mẫu đầu, nên dù người mới không trượt từ chỗ người cũ. Không cấp phát mỗi khung (D-018). */
5	import * as THREE from 'three';
6	import { scene } from '../../core/renderer';
7	import { CONFIG } from '../../config';
8	import { exBuildGlider, exPlaceGlider } from '../glider';
9	import type { GliderState } from '../flight';
10	import { ExTrack, type ExPose } from './interp';
11	import type { Flyer } from './protocol';
12	
13	const M = CONFIG.explore.multi;
14	
15	interface RemoteSlot {
16	  name: string | null;        // null = slot trống
17	  group: THREE.Group | null;
18	  track: ExTrack;
19	  pose: ExPose;               // đệm lấy mẫu
20	  state: GliderState;         // trạng thái trả cho exPlaceGlider và slotState
21	  live: boolean;              // đã có mẫu và đang hiện
22	}
23	
24	const slots: RemoteSlot[] = Array.from({ length: M.slots }, () => ({
25	  name: null, group: null, track: new ExTrack(), pose: { x: 0, y: 0, z: 0, yaw: 0, bank: 0 },
26	  state: { pos: new THREE.Vector3(), yaw: 0, bank: 0, ret: 0, speed: 0 }, live: false
27	}));
28	let me = -1;
29	
30	function hide(s: RemoteSlot): void {
31	  s.track.reset(); s.live = false;
32	  if (s.group) s.group.visible = false;
33	}
34	
35	export const exRemotes = {
36	  /* Danh sách người bay đổi (sảnh, vào, ra): dựng dù cho slot mới, đặt lại slot đổi chủ, ẩn slot trống */
37	  sync(flyers: Flyer[], mySlot: number): void {
38	    me = mySlot;
39	    for (let i = 0; i < slots.length; i++) {
40	      const s = slots[i];
41	      let name: string | null = null;
42	      if (i !== mySlot) for (const f of flyers) if (f.slot === i) { name = f.name; break; }
43	      if (name === null) { s.name = null; hide(s); continue; }
44	      if (name !== s.name) {
45	        s.name = name; hide(s);
46	        if (!s.group) { s.group = exBuildGlider(M.colors[i % M.colors.length]); s.group.visible = false; s.group.traverse(o => o.layers.set(1)); scene.add(s.group); }   // lớp 1: không vẽ vào phản chiếu nước, giữ draw call ≈ 1 mỗi dù
47	      }
48	    }
49	  },
50	
51	  /* Gói vị trí gộp: f = [slot, x, y, z, yaw, bank, giờ gửi?]; chỉ nhận slot đã biết chủ và không phải của mình */
52	  onPos(f: number[][], nowMs: number): void {
53	    for (const e of f) {
54	      const i = e[0], s = slots[i];
55	      if (!s || i === me || s.name === null) continue;
56	      s.track.feed(e, nowMs, M);
57	    }
58	  },
59	
60	  update(nowMs: number): void {
61	    const t = nowMs - M.interpSends * 1000 / M.sendHz;
62	    for (const s of slots) {
63	      if (s.name === null || !s.group) continue;
64	      if (!s.track.sample(t, s.pose)) { s.live = false; s.group.visible = false; continue; }
65	      const p = s.pose;
66	      s.state.pos.set(p.x, p.y, p.z); s.state.yaw = p.yaw; s.state.bank = p.bank;
67	      exPlaceGlider(s.group, s.state);
68	      s.group.visible = s.live = true;
69	    }
70	  },
71	
72	  /* Trạng thái đã nội suy của dù ở slot (cho nhãn tên); null nếu chưa có hoặc slot trống */
73	  slotState(slot: number): GliderState | null {
74	    const s = slots[slot];
75	    return s && s.live ? s.state : null;
76	  },
77	
78	  /* Dù và tên của slot (cho nhãn tên và test); null nếu slot trống */
79	  group(slot: number): THREE.Group | null { const s = slots[slot]; return s && s.name !== null ? s.group : null; },
80	  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },
81	
82	  /* Rời phòng: ẩn hết, quên tên (dù đã dựng giữ lại để tái dùng) */
83	  clear(): void {
