1	import { CONFIG } from '../../config';
2	
3	/* =====================================================================
4	   DÁNG ĐI / DÁNG CHẠY NGƯỜI ĐI BỘ — bản CPU của shader trong material.ts (spec §5, G6, G7).
5	   Shader mới là chỗ chạy thật; file này giữ cùng công thức để unit test kiểm (tests/people-unit/gait.test.ts)
6	   và để code dựng tính nhịp bước (aVar.w) cho từng người. Đổi công thức ở đây thì sửa cả PP_GLSL_ANGLES trong material.ts.
7	   Góc dương = đưa về phía trước (người hướng +X, quay quanh trục Z). φ là pha chu kỳ hai bước:
8	   chân trái φ, chân phải φ + π, tay ngược pha chân cùng bên. Trộn đi ↔ chạy theo biên độ: run = smoothstep(0,42; 0,6; A).
9	   ===================================================================== */
10	export type PersonKind = 'walk' | 'run' | 'stand';
11	export type PersonPart = 'legL' | 'legR' | 'armL' | 'armR';
12	const P = CONFIG.people;
13	
14	const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
15	const smoothstep = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
16	/* Mức chạy 0..1 theo biên độ hông (đi 0,34 → 0, chạy 0,6 → 1) */
17	export const ppRunMix = (amp: number) => smoothstep(0.42, 0.6, amp);
18	/* Biên độ hông theo kiểu người */
19	export const ppAmp = (kind: PersonKind) => (kind === 'walk' ? P.walk.amp : kind === 'run' ? P.run.amp : 0);
20	
21	/* Nhịp (rad/s của φ). Đi: chân trụ không trượt ⇔ ω · bước / 2π = v. Chạy: nhịp cố định, người nhỏ bước nhanh hơn. Đứng: 0 */
22	export function ppCadence(kind: PersonKind, speed: number, scale: number): number {
23	  if (kind === 'walk') return (2 * Math.PI * speed) / (4 * P.legLength * scale * Math.sin(P.walk.amp));
24	  if (kind === 'run') return P.run.cadence / Math.sqrt(scale);
25	  return 0;
26	}
27	
28	/* Quãng đường một chu kỳ hai bước (m): mỗi bước chân trụ quét dây cung 2·L·sin A. Chạy ở tỉ lệ 1 ≈ 1,94 m, khớp 2,6–3,0 m/s ở 1,4 chu kỳ/giây */
29	export function ppStride(kind: PersonKind, scale: number): number {
30	  return kind === 'stand' ? 0 : 4 * P.legLength * scale * Math.sin(ppAmp(kind));
31	}
32	
33	/* Góc khớp: root = hông / vai, joint = gối (≤ 0, gập về sau) / khuỷu (≥ 0, gập về trước). Không tính tư thế chụp ảnh (cờ, chỉ có trong shader) */
34	export function ppAngles(part: PersonPart, amp: number, phase: number): { root: number; joint: number } {
35	  const A = amp, run = ppRunMix(A);
36	  if (part === 'legL' || part === 'legR') {
37	    const f = part === 'legL' ? phase : phase + Math.PI;
38	    const sw = Math.max(0, Math.cos(f - 0.35)), sr = Math.max(0, Math.cos(f + 0.45));   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
39	    const knee = A * 2 * sw * sw + (A >= 0.01 ? 0.06 : 0);
40	    return { root: A * Math.sin(f) + lerp(0.12 * A, 0.22, run), joint: -lerp(knee, 0.38 + 1.5 * sr * sr, run) };
41	  }
42	  const f = part === 'armL' ? phase + Math.PI : phase;
43	  return { root: A * (0.65 + run * 0.5) * Math.sin(f) - 0.05, joint: 0.16 + run * 1.25 + A * 0.35 * Math.max(0, Math.sin(f)) };
44	}
45

1	import * as THREE from 'three';
2	import { CONFIG } from '../../config';
3	import { shared } from '../../core/shared';
4	
5	/* =====================================================================
6	   VẬT LIỆU NGƯỜI ĐI BỘ — một vật liệu dùng chung cho mọi hệ người (spec G5–G8, §5), theo patchPerson của bản dựng thử.
7	   Tay chân vung trong vertex shader theo shared.uTime, không cập nhật đỉnh trên CPU. Công thức góc khớp giống hệt gait.ts (ppAngles).
8	   Thuộc tính instance (bên dựng gắn vào hình học của từng InstancedMesh):
9	   - aVar (vec4): x pha φ0 (rad), y biên độ hông A (0 đứng, walk.amp, run.amp), z cờ (1 nón lá, 2 ba lô, 4 chụp ảnh), w nhịp (rad/s, ppCadence)
10	   - aPants (vec3): màu quần tuyến tính; màu áo qua instanceColor (setColorAt — bắt buộc gọi để có USE_INSTANCING_COLOR)
11	   Người không đổ bóng, không vào phản chiếu (spec §6) nên không có vật liệu bóng riêng. Không emissive, không texture.
12	   Không thêm vào tập bóc mặt cắt hầm (cutaway.ts): người không đứng trong vùng bóc, vật liệu người cũ cũng không có trong tập đó.
13	   ===================================================================== */
14	const P = CONFIG.people;
15	const f = (x: number) => x.toFixed(4);   // số → hằng GLSL
16	
17	/* pAngles: x góc khớp gốc (hông / vai), y góc khớp giữa (gối / khuỷu); dương = đưa về phía trước. Bản CPU: gait.ts ppAngles */
18	const VS_HEAD = /* glsl */`
19	attribute float aPart;
20	attribute float aSeg;
21	attribute float aPivot;
22	attribute float aPivot2;
23	attribute float aMask;
24	attribute vec3 aFix;
25	attribute vec4 aVar;
26	attribute vec3 aPants;
27	uniform float uTime;
28	float pFlag( float b ) { return mod( floor( aVar.z / b ), 2.0 ); }
29	float pRunMix() { return smoothstep( 0.42, 0.6, aVar.y ); }
30	float pPhase() { return uTime * aVar.w + aVar.x; }
31	vec2 pAngles() {
32	  float A = aVar.y, ph = pPhase(), run = pRunMix();
33	  if ( aPart > 0.5 && aPart < 2.5 ) {
34	    float fl = aPart < 1.5 ? ph : ph + 3.14159265;
35	    float sw = max( 0.0, cos( fl - 0.35 ) ), sr = max( 0.0, cos( fl + 0.45 ) );   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
36	    return vec2( A * sin( fl ) + mix( 0.12 * A, 0.22, run ), -mix( A * 2.0 * sw * sw + 0.06 * step( 0.01, A ), 0.38 + 1.5 * sr * sr, run ) );
37	  }
38	  if ( aPart > 2.5 && aPart < 4.5 ) {
39	    float fa = aPart < 3.5 ? ph + 3.14159265 : ph;
40	    if ( aPart > 3.5 && pFlag( 4.0 ) > 0.5 ) return vec2( ${f(P.photo.shoulder)}, ${f(P.photo.elbow)} );   // giơ tay phải chụp ảnh
41	    return vec2( A * ( 0.65 + run * 0.5 ) * sin( fa ) - 0.05, 0.16 + run * 1.25 + A * 0.35 * max( 0.0, sin( fa ) ) );
42	  }
43	  return vec2( 0.0 );
44	}
45	vec2 pRot( vec2 p, float a ) { float c = cos( a ), s = sin( a ); return vec2( p.x * c - p.y * s, p.x * s + p.y * c ); }
46	`;
47	// pháp tuyến quay cùng khớp (beginnormal_vertex chạy trước begin_vertex nên ppA dùng lại được)
48	const VS_NORMAL = /* glsl */`#include <beginnormal_vertex>
49	vec2 ppA = pAngles();
50	float ppLean = ( aPart < 0.5 || aPart > 2.5 ) ? -${f(P.run.lean)} * pRunMix() : 0.0;
51	objectNormal.xy = pRot( objectNormal.xy, ppA.x + ( aSeg > 0.5 ? ppA.y : 0.0 ) + ppLean );`;
52	const VS_POS = /* glsl */`#include <begin_vertex>
53	if ( aSeg > 0.5 ) transformed.xy = pRot( transformed.xy - vec2( 0.0, aPivot2 ), ppA.y ) + vec2( 0.0, aPivot2 );
54	transformed.xy = pRot( transformed.xy - vec2( 0.0, aPivot ), ppA.x ) + vec2( 0.0, aPivot );
55	transformed.xy = pRot( transformed.xy - vec2( 0.0, ${f(P.legLength)} ), ppLean ) + vec2( 0.0, ${f(P.legLength)} );   // chạy: thân, đầu, tay đổ về trước quanh hông
56	if ( aPart > 4.5 && aPart < 5.5 && pFlag( 1.0 ) < 0.5 ) transformed = vec3( 0.0 );   // không đội nón: thu về gốc (tam giác suy biến)
57	if ( aPart > 5.5 && pFlag( 2.0 ) < 0.5 ) transformed = vec3( 0.0 );                  // không đeo ba lô
58	float ppPh = pPhase(), ppMove = step( 0.01, aVar.y );
59	transformed.y += mix( ${f(P.bob.walk)} * cos( 2.0 * ppPh ) - ${f(P.bob.walk)}, ${f(P.bob.run)} * ( 0.5 - 0.5 * cos( 2.0 * ppPh ) ), pRunMix() ) * ppMove;   // đi: thấp nhất khi hai chân dang rộng; chạy: bật lên giữa hai bước
60	transformed.z += ${f(P.sway)} * sin( ppPh ) * ppMove * smoothstep( 0.3, 1.6, transformed.y );   // lắc vai nhẹ sang hai bên`;
61	const VS_COLOR = /* glsl */`#include <color_vertex>
62	#ifdef USE_INSTANCING_COLOR
63	vColor.rgb = aMask < 0.5 ? aFix : ( aMask < 1.5 ? instanceColor.rgb : aPants );   // cố định / áo / quần
64	#endif`;
65	
66	let mat: THREE.MeshStandardMaterial | null = null;
67	/* Một vật liệu cho mọi hệ người (tạo lần đầu gọi) */
68	export function ppMaterial(): THREE.MeshStandardMaterial {
69	  if (mat) return mat;
70	  const m = new THREE.MeshStandardMaterial({ roughness: P.roughness });
71	  m.name = 'peopleWalk';
72	  m.onBeforeCompile = (s) => {
73	    s.uniforms.uTime = shared.uTime;
74	    s.vertexShader = VS_HEAD + s.vertexShader.replace('#include <beginnormal_vertex>', VS_NORMAL).replace('#include <begin_vertex>', VS_POS).replace('#include <color_vertex>', VS_COLOR);
75	    m.userData.vs = s.vertexShader;
76	  };
77	  m.customProgramCacheKey = () => 'peopleWalk';
78	  return (mat = m);
79	}
80

1	import { CONFIG } from '../../config';
2	import { rng } from '../math';
3	import type { PersonKind } from './gait';
4	
5	/* =====================================================================
6	   CHIA KIỂU NGƯỜI (spec G8, §7) — chọn theo chỉ số trên danh sách người đang có, tổng số không đổi.
7	   Dùng rng(seed) riêng (không gọi rand(), không đụng rnd của cầu). Số người mỗi kiểu = làm tròn n × CONFIG.people.mix.
8	   - Người đi cùng (đi đôi hoặc trẻ em) i luôn theo người i − 1; người i − 1 đi bộ một mình (không chạy, không đứng, không đi cùng ai).
9	   - Trẻ em: tỉ lệ childScale, luôn là người đi cùng. Người chụp ảnh: chỉ trong số người đứng.
10	   - flags = tổng cờ PP_FLAG (khớp aVar.z trong material.ts).
11	   ===================================================================== */
12	export const PP_FLAG = { hat: 1, pack: 2, photo: 4 } as const;
13	export interface PersonInfo { kind: PersonKind; scale: number; flags: number; phase: number; follow: number /* chỉ số người mình đi cùng, −1 nếu không */ }
14	
15	/* Xáo trộn Fisher–Yates bằng bộ sinh r */
16	function ppShuffle<T>(a: T[], r: () => number): T[] {
17	  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
18	  return a;
19	}
20	
21	export function ppAssignKinds(n: number, seed: number, opts?: { run?: boolean }): PersonInfo[] {
22	  const P = CONFIG.people, M = P.mix, r = rng(seed), [s0, s1] = P.adultScale;
23	  const out: PersonInfo[] = Array.from({ length: n }, () => ({ kind: 'walk' as PersonKind, scale: s0 + r() * (s1 - s0), flags: 0, phase: r() * Math.PI * 2, follow: -1 }));
24	  // người đi cùng: chọn chỉ số i ≥ 1 sao cho i − 1 và i + 1 không cũng là người đi cùng (người dẫn không đi cùng ai)
25	  const comp = new Set<number>(), nComp = Math.round(n * M.companion);
26	  for (const i of ppShuffle(Array.from({ length: Math.max(0, n - 1) }, (_, k) => k + 1), r)) {
27	    if (comp.size >= nComp) break;
28	    if (!comp.has(i - 1) && !comp.has(i + 1)) comp.add(i);
29	  }
30	  const compList = [...comp].sort((a, b) => a - b);
31	  for (const i of compList) out[i].follow = i - 1;
32	  for (const i of ppShuffle(compList.slice(), r).slice(0, Math.round(compList.length * M.child))) out[i].scale = P.childScale;
33	  // người đứng và người chạy: lấy từ những người không đi cùng và không dẫn ai
34	  const free = ppShuffle(out.map((_, i) => i).filter((i) => !comp.has(i) && !comp.has(i + 1)), r);
35	  const nStand = Math.min(free.length, Math.round(n * M.stand)), nRun = opts?.run === false ? 0 : Math.min(free.length - nStand, Math.round(n * M.run));
36	  const stand = free.slice(0, nStand);
37	  for (const i of stand) out[i].kind = 'stand';
38	  for (const i of free.slice(nStand, nStand + nRun)) out[i].kind = 'run';
39	  // cờ: nón lá, ba lô trên mọi người; chụp ảnh trong số người đứng
40	  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.hat))) out[i].flags |= PP_FLAG.hat;
41	  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.pack))) out[i].flags |= PP_FLAG.pack;
42	  for (const i of ppShuffle(stand.slice(), r).slice(0, Math.round(stand.length * M.photo))) out[i].flags |= PP_FLAG.photo;
43	  return out;
44	}
45

1	/* ===== Dù lượn nhiều người: nội suy vị trí dù người khác (thuần, không import) =====
2	   Vòng đệm cố định 8 mẫu (t, x, y, z, yaw, bank), nội suy tuyến tính, yaw đi đường ngắn qua ±π, kẹp ở mẫu cuối. Không cấp phát khi push/sample (D-018).
3	   Mẫu đặt theo giờ của người gửi (e[6]) quy ra giờ khách, nên trễ mạng và việc máy chủ gộp gói không làm dù đứng rồi vọt. */
4	const N = 8, W = 6;   // số mẫu tối đa; số trường mỗi mẫu
5	export interface ExPose { x: number; y: number; z: number; yaw: number; bank: number }
6	export interface ExClockParams { clockRelax: number; clockSlewMs: number; clockWarmup: number }   // xem multiParams
7	
8	export class ExTrack {
9	  private buf = new Float64Array(N * W);
10	  private head = 0;      // chỉ số ô sẽ ghi tiếp
11	  private n = 0;         // số mẫu đang có
12	  private off = NaN;     // độ lệch giờ người gửi → giờ khách (ms); NaN = chưa có mẫu nào có giờ
13	  private fed = 0;       // số mẫu có giờ đã nhận: clockWarmup mẫu đầu lấy thẳng mức nhỏ nhất (gói đầu có thể trễ vì khung hình chậm), sau đó mới giới hạn slew
14	  get count(): number { return this.n; }
15	
16	  push(t: number, x: number, y: number, z: number, yaw: number, bank: number): void {
17	    if (this.n > 0 && t <= this.buf[((this.head + N - 1) % N) * W]) return;   // mẫu cũ hoặc trùng giờ: bỏ để giữ thứ tự
18	    const o = this.head * W, b = this.buf;
19	    b[o] = t; b[o + 1] = x; b[o + 2] = y; b[o + 3] = z; b[o + 4] = yaw; b[o + 5] = bank;
20	    this.head = (this.head + 1) % N;
21	    if (this.n < N) this.n++;
22	  }
23	
24	  /* Một mục của gói pos e = [slot, x, y, z, yaw, bank, giờ gửi?] nhận lúc nowMs.
25	     Có giờ gửi (máy chủ mới): giờ khách = giờ gửi + độ lệch; độ lệch bám mức nhỏ nhất (gói ít trễ nhất) nhưng sau clockWarmup mẫu đầu mỗi mẫu chỉ giảm tối đa clockSlewMs,
26	     và nới lên clockRelax phần chênh khi mạng chậm đi: độ lệch đổi chậm nên dù không bị co giãn thời gian.
27	     Không có (máy chủ cũ phát lại vị trí cũ của mọi slot mỗi gói): đóng dấu giờ nhận, bỏ mục trùng mẫu cuối để dù không đứng chờ */
28	  feed(e: number[], nowMs: number, k: ExClockParams): void {
29	    const ts = e[6];
30	    if (typeof ts === 'number' && Number.isFinite(ts)) {
31	      const c = nowMs - ts;
32	      if (this.off !== this.off || (c < this.off && this.fed < k.clockWarmup)) this.off = c;
33	      else if (c < this.off) this.off -= Math.min(this.off - c, k.clockSlewMs);
34	      else this.off += (c - this.off) * k.clockRelax;
35	      this.fed++;
36	      this.push(ts + this.off, e[1], e[2], e[3], e[4], e[5]);
37	      return;
38	    }
39	    if (this.n > 0) {
40	      const o = ((this.head + N - 1) % N) * W, b = this.buf;
41	      if (b[o + 1] === e[1] && b[o + 2] === e[2] && b[o + 3] === e[3] && b[o + 4] === e[4] && b[o + 5] === e[5]) return;
42	    }
43	    this.push(nowMs, e[1], e[2], e[3], e[4], e[5]);
44	  }
45	
46	  /* Ghi vị trí tại thời điểm t vào out; false nếu chưa có mẫu */
47	  sample(t: number, out: ExPose): boolean {
48	    if (this.n === 0) return false;
49	    const b = this.buf, first = (this.head + N - this.n) % N * W;
50	    const last = ((this.head + N - 1) % N) * W;
51	    let a = first, c = first;
52	    if (t >= b[last]) a = c = last;
53	    else if (t > b[first]) {
54	      for (let i = 0; i < this.n - 1; i++) {
55	        const p = (first + i * W) % (N * W), q = (p + W) % (N * W);
56	        if (t <= b[q]) { a = p; c = q; break; }
57	      }
58	    }
59	    const k = a === c ? 0 : (t - b[a]) / (b[c] - b[a]);
60	    out.x = b[a + 1] + (b[c + 1] - b[a + 1]) * k;
61	    out.y = b[a + 2] + (b[c + 2] - b[a + 2]) * k;
62	    out.z = b[a + 3] + (b[c + 3] - b[a + 3]) * k;
63	    let dy = b[c + 4] - b[a + 4];
64	    dy -= Math.round(dy / (2 * Math.PI)) * 2 * Math.PI;
65	    out.yaw = b[a + 4] + dy * k;
66	    out.bank = b[a + 5] + (b[c + 5] - b[a + 5]) * k;
67	    return true;
68	  }
69	
70	  reset(): void { this.n = 0; this.head = 0; this.off = NaN; this.fed = 0; }
71	}
